    if residual_diff > 10.0 {
        score += residual_diff * 0.2;
    } else {
        score -= residual_diff * 0.1;
    }

    // Favor items that are closer to the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.5 {
        score *= progress * 3.0;
    } else {
        score *= (1.0 - progress) * 2.0;
    }

    score
